"""specs_u69_74.py - area 69, group 74 (slice 8): 51 list-flush functions (one spec per address). Each takes two global pointers (head, tail) that are
node addresses or zero; the nodes are 0x20-byte buffers. The globals 0x7003bc and 0x7003c0 are written by the code and compared."""
from pilot import S
from ckit import rnd


def _gen(g1, g2):
    def gen(c):
        e = c.emu
        r = c.rng
        n1 = rnd(c, 0x20)
        n2 = rnd(c, 0x20)
        e.w32(g1, r.choice([0, n1, n2]))
        e.w32(g2, r.choice([0, n1, n2]))
        e.w32(n1 + 0x14, r.getrandbits(32))
        e.w32(n2 + 0x14, r.getrandbits(32))
        e.w32(n1 + 0x10, r.getrandbits(32))
        e.w32(n2 + 0x10, r.getrandbits(32))
        e.w32(0x7003bc, r.getrandbits(32))
        e.w32(0x7003c0, r.getrandbits(32))
        return [rnd(c, 0x10)]   # the object for ECX (the code does not read it)
    return gen


